import { t } from './i18n.js';

// The plotted observations are the app's bundled Hooke's-law teaching example.
export function axiomPlot() {
  const force=[.51,.98,1.53,2.01,2.48,3.05,3.47,4.04,4.48,5.03,5.49,6.02];
  return `<svg class="axiom-plot" viewBox="0 0 400 280" aria-hidden="true"><g class="axiom-grid">${[70,130,190].map(y=>`<path d="M40 ${y}H372"/>`).join('')}${[120,200,280,360].map(x=>`<path d="M${x} 30V230"/>`).join('')}</g><path class="axiom-axis" d="M40 30V230H372"/><g class="axiom-axis-label"><text x="10" y="14">F / N</text><text x="327" y="260">x / m</text><text x="23" y="234">0</text><text x="17" y="134">3</text><text x="17" y="48">6</text><text x="150" y="249">0.05</text><text x="276" y="249">0.10</text></g><path class="axiom-fit" pathLength="1" d="M40 229.873L365 35.920"/><g class="axiom-observations">${force.map((y,i)=>{const x=40+(i+1)*26,cy=230-y*31;return `<g style="--point:${i}"><path d="M${x-4} ${cy}h8M${x} ${cy-4}v8"/><circle cx="${x}" cy="${cy}" r="4"/></g>`}).join('')}</g><path class="axiom-gradient" d="M144 168H300V75"/><text x="214" y="189" class="axiom-gradient-label">Δy / Δx</text></svg>`;
}
const stats=()=>`<dl class="axiom-stats"><div><dt>09</dt><dd>${t('axiom.charts')}</dd></div><div><dt>22</dt><dd>${t('axiom.formulas')}</dd></div><div><dt>03</dt><dd>${t('axiom.modes')}</dd></div></dl>`;
const actions=project=>`<div class="axiom-actions"><span>${t('axiom.local')}</span><div><a href="${project.repoUrl}" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a class="axiom-launch" href="${project.liveUrl}" target="_blank" rel="noopener noreferrer">${t('axiom.launch')} <span aria-hidden="true">↗</span></a></div></div>`;
export function axiomCard(project) {
  return `<article class="exhibit exhibit--axiom" id="project-axiom"><header class="axiom-masthead"><span><b>A↗</b> THE SCIENTIFIC COLLECTION</span><span>NO. 03 <i>/</i> V1.0</span></header><button class="axiom-open" data-project="axiom" aria-label="${t('project.viewAria',{name:'AXIOM'})}"><div class="axiom-intro"><span class="axiom-overline">MEASURE. PLOT. DISCOVER.</span><h3>AXIOM<span>↗</span></h3><p class="axiom-name">${t('axiom.name')}</p><h4>${t('axiom.headline')}</h4><p class="axiom-description">${t('axiom.description')}</p><span class="axiom-inspect">${t('axiom.inspect')} <b>＋</b></span></div><div class="axiom-stage" aria-hidden="true"><div class="axiom-figure"><div class="axiom-figure-heading"><span>FIGURE / 01</span><span>F = kx</span></div>${axiomPlot()}<div class="axiom-figure-caption"><span>${t('axiom.figure')}</span><b>12 OBSERVATIONS</b></div></div><div class="axiom-studio-strip"><span>RESEARCH</span><span>IB STUDENT</span><span>PROFESSIONAL</span></div><div class="axiom-app-window"><div><b>A↗</b><span>AXIOM / THE WORKSPACE</span><span>01</span></div><img src="./assets/projects/axiom/workspace.png" width="2283" height="1437" alt="" loading="lazy" decoding="async"></div></div></button>${stats()}${actions(project)}</article>`;
}
export function axiomDetail(project) {
  return `<header class="axiom-detail-head"><span class="axiom-overline">CHEFZC / PROJECT 03 / VERSION 1.0.0</span><h2 id="dialog-title">AXIOM<span>↗</span></h2><p>${t('axiom.headline')}</p></header><figure class="axiom-detail-figure"><img src="./assets/projects/axiom/workspace.png" width="2283" height="1437" alt="${t('axiom.capture')}"><figcaption>${t('axiom.capture')}</figcaption></figure>${stats()}<div class="axiom-detail-copy"><section><span class="axiom-overline">01 / THE EXPERIMENT</span><h3>${t('axiom.detailTitle')}</h3><p>${t('axiom.detailText')}</p></section><section><span class="axiom-overline">02 / BEYOND THE SCREEN</span><h3>${t('axiom.export')}</h3><p>${t('axiom.exportText')}</p><p class="axiom-note">${t('axiom.boundary')}</p></section></div>${actions(project)}`;
}
